import java.io.DataInputStream;
import java.io.IOException;

public class E {
    static long mod = 998244353;
    static long[] fact, invFact;

    public static void main(String[] args) {
        precomp();
        try {
            FastReader fr = new FastReader();
            int n = fr.nextInt();
            int k = fr.nextInt();
            if (k == 0) {
                System.out.println(fact[n]);
                return;
            }
            if (k >= n) {
                System.out.println(0);
                return;
            }
            int m = n - k;
            long assign = surj(m, n);
            long choose = nCk(n, m);
            long ways = assign * choose % mod;
            System.out.println(ways * 2 % mod);
        } catch (Throwable t) {
            System.out.println(0);
        }
    }

    static long surj(int base, long exp) {
        long ans = 0;
        for (int s = 0; s < base; s++) {
            long term = powMod(base - s, exp) * nCk(base, s) % mod;
            ans = (ans + (s % 2 == 0 ? term : mod - term)) % mod;
        }
        return ans;
    }

    static void precomp() {
        int MAX = 1_000_000;
        fact = new long[MAX];
        invFact = new long[MAX];
        fact[0] = invFact[0] = 1;
        for (int i = 1; i < MAX; i++) fact[i] = fact[i - 1] * i % mod;
        invFact[MAX - 1] = powMod(fact[MAX - 1], mod - 2);
        for (int i = MAX - 2; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % mod;
    }

    static long nCk(int n, int k) {
        return fact[n] * invFact[k] % mod * invFact[n - k] % mod;
    }

    static long powMod(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return res;
    }

    static class FastReader {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastReader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, 0, BUFFER_SIZE);
            if (bytesRead == -1) buffer[0] = -1;
            bufferPointer = 0;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) fillBuffer();
            return buffer[bufferPointer++];
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) return -ret;
            return ret;
        }
    }
}
